type SystemMessageController interface {
	// ---- 消息配置 ----
	ConfigList(ctx context.Context, req *MessageConfigListRequest) (r *MessageConfigListResponse, err error)

	ConfigGet(ctx context.Context, req *MessageIdRequest) (r *MessageConfigDTO, err error)

	ConfigCreate(ctx context.Context, req *MessageConfigSaveRequest) (r *MessageConfigDTO, err error)

	ConfigUpdate(ctx context.Context, req *MessageConfigSaveRequest) (r *MessageConfigDTO, err error)

	ConfigRemove(ctx context.Context, req *MessageIdRequest) (r int32, err error)
	// ---- 消息常量 ----
	KeyList(ctx context.Context, req *MessageKeyListRequest) (r *MessageKeyListResponse, err error)

	KeyGet(ctx context.Context, req *MessageIdRequest) (r *MessageKeyDTO, err error)

	KeyCreate(ctx context.Context, req *MessageKeySaveRequest) (r *MessageKeyDTO, err error)

	KeyUpdate(ctx context.Context, req *MessageKeySaveRequest) (r *MessageKeyDTO, err error)

	KeyRemove(ctx context.Context, req *MessageIdRequest) (r int32, err error)
	// ---- 消息模板 ----
	TemplateList(ctx context.Context, req *MessageTemplateListRequest) (r *MessageTemplateListResponse, err error)

	TemplateGet(ctx context.Context, req *MessageIdRequest) (r *MessageTemplateDTO, err error)

	TemplateCreate(ctx context.Context, req *MessageTemplateSaveRequest) (r *MessageTemplateDTO, err error)

	TemplateUpdate(ctx context.Context, req *MessageTemplateSaveRequest) (r *MessageTemplateDTO, err error)

	TemplateRemove(ctx context.Context, req *MessageIdRequest) (r int32, err error)
	// 测试发送（走发送服务，无论成败都落发送记录）
	TemplateSendTest(ctx context.Context, req *MessageSendTestRequest) (r *MessageSendTestResponse, err error)
	// ---- 发送记录 ----
	LogList(ctx context.Context, req *MessageLogListRequest) (r *MessageLogListResponse, err error)

	LogGet(ctx context.Context, req *MessageIdRequest) (r *MessageLogDTO, err error)
	// 删除单条发送记录，返回删除条数
	LogRemove(ctx context.Context, req *MessageIdRequest) (r int64, err error)
	// 清空发送记录，返回删除条数
	LogClear(ctx context.Context) (r int64, err error)
	// ---- 元数据 ----
	Suppliers(ctx context.Context, req *MessageSuppliersRequest) (r *MessageSuppliersResponse, err error)

	FieldConfigs(ctx context.Context) (r *MessageFieldConfigsResponse, err error)
}

